from pathlib import Path
import json
menu=json.loads(Path('data/image-audit.json').read_text(encoding='utf8'))['drinks'];studio=json.loads(Path('data/generated-image-manifest.json').read_text(encoding='utf8'));brand=json.loads(Path('data/branded-image-manifest.json').read_text(encoding='utf8'));reviewed=set(json.loads(Path('data/branded-reviewed-ids.json').read_text(encoding='utf8')))
retained={m['id']:brand[m['id']]['image'] if m['id'] in reviewed else studio[m['id']]['image'] for m in menu[:30]}
