jobs=json.loads(Path('data/brand-generation-jobs.json').read_text(encoding='utf8'));jobs=[m for m in jobs if m['id'] not in retained];Path('data/remaining-brand-jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2),encoding='utf8');print('Retained:',len(retained),'Remaining branded cups:',len(jobs))
p=Path('scripts/apply_branded.py');s=p.read_text(encoding='utf-8-sig');s=s.replace("for m in audit['drinks']:","retained=json.loads(Path('data/retained-first-30-images.json').read_text(encoding='utf8'))\nfor m in audit['drinks']:");s=s.replace(" if m['id'] in reviewed", " if m['id'] in retained:m['image']=retained[m['id']];m['imageTreatment']='Approved existing generated photo retained without regeneration'\n elif m['id'] in reviewed");s=s.replace("print('Applied',len(reviewed),'branded photos; other photographs restored')","print('Retained',len(retained),'existing photos; applied',len(reviewed),'reviewed brand replacements')");p.write_text(s,encoding='utf8')
